from types import SimpleNamespace

import pytest

from rest_framework.permissions import (
    DjangoModelPermissions,
    DjangoModelPermissionsOrAnonReadOnly,
)


PERMISSION_CLASSES = (
    DjangoModelPermissions,
    DjangoModelPermissionsOrAnonReadOnly,
)
VIEW_INTERFACES = ('queryset', 'get_queryset')


class User:
    def __init__(self, authenticated, permissions=()):
        self.is_authenticated = authenticated
        self.permissions = set(permissions)

    def has_perms(self, permission_names):
        return all(name in self.permissions for name in permission_names)


def make_view(interface):
    model = SimpleNamespace(
        _meta=SimpleNamespace(app_label='demo', model_name='item')
    )
    queryset = SimpleNamespace(model=model)
    if interface == 'queryset':
        return SimpleNamespace(queryset=queryset)
    return SimpleNamespace(get_queryset=lambda: queryset)


def check(permission_class, interface, method, authenticated, permissions):
    request = SimpleNamespace(
        method=method,
        user=User(authenticated, permissions),
    )
    return permission_class().has_permission(request, make_view(interface))


def assert_write_permission(permission_class, interface, method, action):
    required = f'demo.{action}_item'
    unrelated = {
        f'demo.{other}_item'
        for other in ('add', 'change', 'delete', 'view')
        if other != action
    }
    unrelated.update({f'other.{action}_item', f'demo.{action}_other'})

    assert check(permission_class, interface, method, True, {required})
    assert check(
        permission_class, interface, method, True, unrelated | {required}
    )
    assert not check(permission_class, interface, method, True, set())
    assert not check(permission_class, interface, method, True, unrelated)


@pytest.mark.parametrize('permission_class', PERMISSION_CLASSES)
@pytest.mark.parametrize('interface', VIEW_INTERFACES)
@pytest.mark.parametrize('method', ('POST', 'PUT', 'PATCH', 'DELETE'))
def test_unauthenticated_writes_are_denied(permission_class, interface, method):
    permissions = {
        'demo.add_item',
        'demo.change_item',
        'demo.delete_item',
        'demo.view_item',
    }
    assert not check(permission_class, interface, method, False, permissions)


@pytest.mark.parametrize('permission_class', PERMISSION_CLASSES)
@pytest.mark.parametrize('interface', VIEW_INTERFACES)
def test_post_requires_model_add_permission(permission_class, interface):
    assert_write_permission(permission_class, interface, 'POST', 'add')


@pytest.mark.parametrize('permission_class', PERMISSION_CLASSES)
@pytest.mark.parametrize('interface', VIEW_INTERFACES)
def test_put_requires_model_change_permission(permission_class, interface):
    assert_write_permission(permission_class, interface, 'PUT', 'change')


@pytest.mark.parametrize('permission_class', PERMISSION_CLASSES)
@pytest.mark.parametrize('interface', VIEW_INTERFACES)
def test_patch_requires_model_change_permission(permission_class, interface):
    assert_write_permission(permission_class, interface, 'PATCH', 'change')


@pytest.mark.parametrize('permission_class', PERMISSION_CLASSES)
@pytest.mark.parametrize('interface', VIEW_INTERFACES)
def test_delete_requires_model_delete_permission(permission_class, interface):
    assert_write_permission(permission_class, interface, 'DELETE', 'delete')

from types import SimpleNamespace

import pytest
from rest_framework.permissions import (
    DjangoModelPermissions,
    DjangoModelPermissionsOrAnonReadOnly,
)


class User:
    def __init__(self, permissions=(), authenticated=True):
        self.is_authenticated = authenticated
        self.permissions = set(permissions)

    def has_perms(self, permission_names):
        return all(name in self.permissions for name in permission_names)


@pytest.fixture(params=[DjangoModelPermissions, DjangoModelPermissionsOrAnonReadOnly])
def checker(request):
    return request.param()


@pytest.fixture(params=['queryset', 'get_queryset'])
def view_kind(request):
    return request.param


def make_view(view_kind, model_name='item'):
    model = type('Model', (), {
        '_meta': SimpleNamespace(app_label='demo', model_name=model_name),
    })
    queryset = SimpleNamespace(model=model)
    if view_kind == 'queryset':
        return SimpleNamespace(queryset=queryset)
    return SimpleNamespace(get_queryset=lambda: queryset)


def allowed(checker, view, method, permissions=(), authenticated=True):
    request = SimpleNamespace(
        method=method,
        user=User(permissions, authenticated=authenticated),
    )
    return checker.has_permission(request, view)


def test_post_requires_add_permission(checker, view_kind):
    view = make_view(view_kind)
    assert allowed(checker, view, 'POST', {'demo.add_item'})
    assert not allowed(checker, view, 'POST')
    assert not allowed(checker, view, 'POST', {
        'demo.change_item', 'demo.delete_item',
    })


@pytest.mark.parametrize('method', ['PUT', 'PATCH'])
def test_put_and_patch_require_change_permission(checker, view_kind, method):
    view = make_view(view_kind)
    assert allowed(checker, view, method, {'demo.change_item'})
    assert not allowed(checker, view, method)
    assert not allowed(checker, view, method, {
        'demo.add_item', 'demo.delete_item',
    })


def test_delete_requires_delete_permission(checker, view_kind):
    view = make_view(view_kind)
    assert allowed(checker, view, 'DELETE', {'demo.delete_item'})
    assert not allowed(checker, view, 'DELETE')
    assert not allowed(checker, view, 'DELETE', {
        'demo.add_item', 'demo.change_item',
    })


@pytest.mark.parametrize('method', ['POST', 'PUT', 'PATCH', 'DELETE'])
def test_unauthenticated_writes_are_denied(checker, view_kind, method):
    assert not allowed(
        checker,
        make_view(view_kind),
        method,
        {'demo.add_item', 'demo.change_item', 'demo.delete_item'},
        authenticated=False,
    )


@pytest.mark.parametrize('method, action', [
    ('POST', 'add'),
    ('PUT', 'change'),
    ('PATCH', 'change'),
    ('DELETE', 'delete'),
])
def test_permissions_follow_the_view_model(checker, view_kind, method, action):
    view = make_view(view_kind, model_name='other')
    assert not allowed(checker, view, method, {f'demo.{action}_item'})
    assert allowed(checker, view, method, {f'demo.{action}_other'})
